import heapq


def order(deps):
    nodes = set()
    indegree = {}
    adj = {}

    for node, prereqs in deps.items():
        nodes.add(node)

        if isinstance(prereqs, str):
            unique_prereqs = {prereqs}
        else:
            unique_prereqs = set(prereqs or ())

        indegree.setdefault(node, 0)

        for prereq in unique_prereqs:
            nodes.add(prereq)
            indegree[prereq] = indegree.get(prereq, 0) + 1
            adj.setdefault(prereq, set()).add(node)

    for node in nodes:
        indegree.setdefault(node, 0)
        adj.setdefault(node, set())

    ready = [node for node, count in indegree.items() if count == 0]
    heapq.heapify(ready)

    result = []

    while ready:
        node = heapq.heappop(ready)
        result.append(node)

        for dependent in adj[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

